import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.BY72S51x.js";const d="/aibutler/docs-versions/v1.1.9/img/settings-search.png",u=JSON.parse('{"title":"联网搜索","description":"","frontmatter":{},"headers":[],"relativePath":"guide/search.md","filePath":"guide/search.md"}'),i={name:"guide/search.md"};function o(s,t,n,c,h,p){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="联网搜索" tabindex="-1">联网搜索 <a class="header-anchor" href="#联网搜索" aria-label="Permalink to &quot;联网搜索&quot;">​</a></h1><p>人格能上网搜资料。用 Butler 引擎的人格，搜索方式在系统设置里定；用 Claude 订阅的人格走 Claude 自己的搜索，不受这里影响。</p><h2 id="默认-用模型自带的搜索" tabindex="-1">默认：用模型自带的搜索 <a class="header-anchor" href="#默认-用模型自带的搜索" aria-label="Permalink to &quot;默认：用模型自带的搜索&quot;">​</a></h2><p>什么都不配时，人格用模型服务商自带的搜索。Claude、OpenAI 这类模型一般都有；有的模型或网关没有，那就搜不了。</p><h2 id="自己加搜索引擎" tabindex="-1">自己加搜索引擎 <a class="header-anchor" href="#自己加搜索引擎" aria-label="Permalink to &quot;自己加搜索引擎&quot;">​</a></h2><p>系统设置 →「工具」→「联网搜索」：</p><ol><li>点「＋ 添加」，在弹出的列表里选一家：Brave、Tavily 或 SearXNG。</li><li>要 Key 的填 Key，SearXNG 填你自己的服务地址。</li><li>点「测一下」，看到「能用」和第一条结果就对了。</li><li>加了好几家时，用 ↑↓ 排先后，排在上面的先用；一家不通，自动换下一家。</li><li>关掉设置窗口时会问你改动要不要保存，点「保存」。</li></ol><p><img src="'+d+'" alt="联网搜索设置"></p><table tabindex="0"><thead><tr><th>引擎</th><th>要 Key</th><th>中国大陆直连</th></tr></thead><tbody><tr><td>Brave</td><td>要（<a href="https://brave.com/search/api/" target="_blank" rel="noreferrer">申请</a>）</td><td>不能，要代理</td></tr><tr><td>Tavily</td><td>要（<a href="https://tavily.com" target="_blank" rel="noreferrer">申请</a>）</td><td>能</td></tr><tr><td>SearXNG</td><td>填自己的服务地址</td><td>看你的服务器</td></tr></tbody></table><p>在中国大陆推荐加 Tavily，能直连。</p><div class="warning custom-block"><p class="custom-block-title">加了就只用加的</p><p>只要加了引擎，人格就只用这些，不再用模型自带的搜索。想临时换回模型自带的，勾「禁用这些引擎」，加过的配置都留着，取消勾选就恢复。</p></div><p>改完要重新打开人格才生效。</p>',12)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
